// Package postgres implements identity.Admitter against PostgreSQL via
// jackc/pgx. The queries are generated by sqlc from queries.sql.
package postgres

import (
	"context"
	"errors"

	"github.com/jackc/pgx/v5"
	"github.com/jackc/pgx/v5/pgxpool"

	"github.com/garamsh/garam/lib/errorx"
	"github.com/garamsh/garam/lib/grn"
	"github.com/garamsh/garam/platform/internal/identity"
	"github.com/garamsh/garam/platform/internal/identity/postgres/db"
	"github.com/garamsh/garam/platform/internal/operator"
	"github.com/garamsh/garam/platform/internal/pgxerr"
	"github.com/garamsh/garam/platform/internal/pgxtype"
)

// Store implements identity.Admitter.
type Store struct {
	pool *pgxpool.Pool
	q    *db.Queries
}

// Compile-time check that Store satisfies identity.Admitter.
var _ identity.Admitter = (*Store)(nil)

// New constructs a Postgres-backed identity.Admitter.
func New(pool *pgxpool.Pool) *Store {
	return &Store{pool: pool, q: db.New(pool)}
}

// Admit holds the principal's record, reads the database's clock under
// that hold, and spends the assertion's jti, all in one transaction.
// The (principal, jti) primary key is what refuses a replay on any
// replica: a concurrent spend of the same pair waits on the first and
// conflicts once it commits.
func (s *Store) Admit(ctx context.Context, principal grn.GRN, a operator.VerifiedAssertion) error {
	key := principal.String()
	tx, err := s.pool.Begin(ctx)
	if err != nil {
		return errorx.Wrap(err, "begin", errorx.KindUnavailable)
	}
	defer func() { _ = tx.Rollback(ctx) }()

	q := s.q.WithTx(tx)
	decided, err := q.HoldServicePrincipal(ctx, key)
	if errors.Is(err, pgx.ErrNoRows) {
		return s.refuseGone(ctx, q, principal, a)
	}
	if err != nil {
		return storageError(err, "hold service principal")
	}
	now := decided.Time.UTC()
	if !a.Timely(now) {
		return operator.ErrClientInvalid
	}
	if err := q.SweepServiceAssertions(ctx, key); err != nil {
		return storageError(err, "sweep service assertions")
	}
	if _, err := q.SpendServiceAssertion(ctx, db.SpendServiceAssertionParams{
		OperatorGrn: key, Jti: a.JTI, ExpiresAt: pgxtype.Timestamptz(a.ReplayUntil()),
	}); err != nil {
		return storageError(err, "spend service assertion")
	}
	if err := tx.Commit(ctx); err != nil {
		return errorx.Wrap(err, "commit", errorx.KindUnavailable)
	}
	return nil
}

// refuseGone answers an assertion whose principal has no record: an
// organization garam holds none of is [identity.ErrOrganizationUnknown]
// where the assertion is timely, and every other case, a principal gone
// from an organization that exists included, is a client that does not
// authenticate. Nothing is spent for either.
func (s *Store) refuseGone(ctx context.Context, q *db.Queries, principal grn.GRN, a operator.VerifiedAssertion) error {
	held, err := q.OrganizationHeld(ctx, principal.Organization)
	if err != nil {
		return storageError(err, "read organization")
	}
	if held.Held || !a.Timely(held.DecidedAt.Time.UTC()) {
		return operator.ErrClientInvalid
	}
	return identity.ErrOrganizationUnknown
}

// storageError classifies a driver error as pgxerr does, with a record
// or a spend that is not there a refusal rather than an outage, and a
// failure it cannot name as unavailable: a credential read from
// storage that did not answer is unknown, and unknown refuses.
func storageError(err error, op string) error {
	err = pgxerr.Classify(err, op, operator.ErrClientInvalid, nil)
	if err != nil && errorx.KindOf(err) == errorx.KindUnknown {
		return errorx.Wrap(err, op, errorx.KindUnavailable)
	}
	return err
}
